<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WastedToken Mint — Physical Proof of Internet History</title>
<style>
  :root{
    --ink:#07090d; --panel:#0d1118; --line:rgba(255,255,255,.12);
    --paper:#ece7dd; --acid:#b8ff3d; --muted:#9ba4b4;
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{margin:0;background:var(--ink);color:var(--paper);font-family:Arial,Helvetica,sans-serif;letter-spacing:.025em}
  .nav{height:76px;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(22px,5vw,80px);border-bottom:1px solid var(--line);position:relative;z-index:2}
  .brand{font-size:13px;font-weight:900;letter-spacing:.18em;text-transform:uppercase}
  .brand i{color:var(--acid);font-style:normal}
  .nav a{color:var(--paper);font-size:11px;text-decoration:none;text-transform:uppercase;letter-spacing:.14em}
  .hero{min-height:720px;display:grid;place-items:center;padding:35px 20px 65px;background:radial-gradient(ellipse at 50% 43%,#1b2631 0%,#0d1118 38%,#07090d 78%)}
  #coin-hero{width:min(760px,92vw);height:min(590px,72vw);max-height:590px;display:block}
  .intro{padding:110px clamp(22px,10vw,160px);border-top:1px solid var(--line);display:grid;grid-template-columns:minmax(100px,.65fr) minmax(280px,2fr);gap:50px;background:#10151c}
  .eyebrow{font-size:10px;font-weight:800;letter-spacing:.2em;text-transform:uppercase;color:var(--acid)}
  h1,h2,p{margin:0}
  h1{font-size:clamp(38px,6.8vw,88px);line-height:.92;letter-spacing:-.065em;text-transform:uppercase;max-width:900px}
  .intro p{margin-top:28px;max-width:680px;color:#c2c7cf;font-size:17px;line-height:1.65;letter-spacing:0}
  .collection{padding:92px clamp(18px,5vw,80px) 110px}
  .collection-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:34px}
  h2{font-size:clamp(35px,5vw,66px);line-height:.95;letter-spacing:-.06em;text-transform:uppercase}
  .collection-head p{max-width:350px;color:var(--muted);line-height:1.5;font-size:13px}
  .grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line)}
  .edition{min-height:440px;padding:20px;display:flex;flex-direction:column;border-right:1px solid var(--line);background:linear-gradient(145deg,#121821,#090c11)}
  .edition:last-child{border-right:0}
  .edition-canvas{width:100%;aspect-ratio:1.08;display:block}
  .edition .meta{margin-top:auto;border-top:1px solid var(--line);padding-top:17px}
  .edition h3{margin:0 0 7px;font-size:20px;letter-spacing:-.035em;text-transform:uppercase}
  .edition p{margin:0;color:var(--muted);font-size:10px;font-weight:bold;letter-spacing:.12em;text-transform:uppercase}
  .edition .status{margin-top:12px;color:var(--acid)}
  .edition[data-state="sold-out"] .status{color:#ff746c}
  .edition[data-state="coming-soon"] .status{color:#9ca7ba}
  button.buy{margin-top:17px;border:0;background:var(--acid);color:#071008;padding:13px 12px;font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;cursor:pointer}
  button.buy:hover{background:#d2ff7e}
  .toast{position:fixed;left:50%;bottom:25px;transform:translate(-50%,120px);background:var(--acid);color:#07090d;padding:13px 20px;font-size:11px;font-weight:bold;text-transform:uppercase;transition:transform .25s;z-index:8}
  .toast.show{transform:translate(-50%,0)}
  footer{border-top:1px solid var(--line);padding:25px clamp(22px,5vw,80px);font-size:10px;letter-spacing:.14em;color:#798394;text-transform:uppercase}
  @media(max-width:760px){
    .hero{min-height:490px}.intro{grid-template-columns:1fr;padding:75px 28px;gap:25px}
    .grid{grid-template-columns:repeat(2,1fr)}.edition:nth-child(2){border-right:0}.edition:nth-child(-n+2){border-bottom:1px solid var(--line)}
    .edition{min-height:355px;padding:14px}
  }
</style>
</head>
<body>
<nav class="nav">
  <div class="brand">Wasted<i>Token</i> Mint</div>
  <a href="#collection">The Collection ↓</a>
</nav>

<section class="hero" aria-label="Animated WastedToken Mint challenge coin">
  <canvas id="coin-hero" width="1000" height="760"></canvas>
</section>

<section class="intro">
  <div class="eyebrow">01 / The mint</div>
  <div>
    <h1>Proof that you were terminally online.</h1>
    <p>WastedToken Mint turns the strange, fleeting currency of the internet into heirloom-grade metal. Every challenge coin is struck in small, numbered runs, with deep relief, honest weight, and just enough menace to make a desk look important.</p>
  </div>
</section>

<section class="collection" id="collection">
  <div class="collection-head">
    <div><div class="eyebrow">02 / First strike</div><h2>Choose your<br>currency.</h2></div>
    <p>Four editions. One very real object. Each arrives in a sealed archival sleeve with a serialized mint card.</p>
  </div>
  <div class="grid">
    <div class="edition" data-edition="bronze" data-state="available">
      <canvas class="edition-canvas" aria-label="Bronze WastedToken coin"></canvas>
      <div class="meta"><h3>Bronze</h3><p>First run · 38 mm</p><p class="status">Available · 0.18 ETH</p><button class="buy">Add to cart</button></div>
    </div>
    <div class="edition" data-edition="silver" data-state="available">
      <canvas class="edition-canvas" aria-label="Silver WastedToken coin"></canvas>
      <div class="meta"><h3>Silver</h3><p>Mirror run · 38 mm</p><p class="status">Available · 0.32 ETH</p><button class="buy">Add to cart</button></div>
    </div>
    <div class="edition" data-edition="gold" data-state="sold-out">
      <canvas class="edition-canvas" aria-label="Gold WastedToken coin"></canvas>
      <div class="meta"><h3>Gold</h3><p>Genesis run · 38 mm</p><p class="status">SOLD OUT</p></div>
    </div>
    <div class="edition" data-edition="black" data-state="coming-soon">
      <canvas class="edition-canvas" aria-label="Black obsidian WastedToken coin"></canvas>
      <div class="meta"><h3>Black / Obsidian</h3><p>Night run · 38 mm</p><p class="status">Minting Winter 2026</p></div>
    </div>
  </div>
</section>
<footer>© 2026 WastedToken Mint · Strike it while it matters.</footer>
<div class="toast" id="toast">Coin added to your imaginary vault.</div>

<script>
(() => {
  const canvas = document.getElementById('coin-hero');
  const ctx = canvas.getContext('2d');
  const W=canvas.width,H=canvas.height, CX=W/2,CY=H/2, R=245, TH=23;
  let running=true, start=performance.now(), raf;

  const colors={
    bronze:['#2a1007','#86401a','#f6b55a','#5c260e'],
    silver:['#27323a','#91a9b9','#f4fbff','#536574'],
    gold:['#442700','#a6680a','#fff3a1','#865000'],
    black:['#05070a','#1b2630','#79929b','#10141a']
  };
  function poly(points, fill, stroke){
    ctx.beginPath(); points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill()} if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}
  }
  function norm(v){let d=Math.hypot(...v);return v.map(x=>x/d)}
  function drawCoin(c, options={}){
    const t=options.t ?? .08, pal=colors[options.kind||'silver'], mini=!!options.mini;
    const cx=options.cx??CX, cy=options.cy??CY, r=options.r??R, th=(options.th??TH)*(r/R);
    const y=t*Math.PI*2, x=t*Math.PI*2;
    const u=[Math.cos(y),Math.sin(x)*Math.sin(y),-Math.cos(x)*Math.sin(y)];
    const v=[0,Math.cos(x),Math.sin(x)];
    const n=[Math.sin(y),-Math.sin(x)*Math.cos(y),Math.cos(x)*Math.cos(y)];
    const project=(a,b,z)=>[cx+a*u[0]+b*v[0]+z*n[0],cy+a*u[1]+b*v[1]+z*n[1],a*u[2]+b*v[2]+z*n[2]];
    const faceSign=n[2]>=0?1:-1, faceIsFront=faceSign===1;
    // thick reeded wall; individually shaded ridges establish a real milled edge
    for(let i=0;i<100;i++){
      const a=i*Math.PI*2/100, b=(i+1)*Math.PI*2/100;
      const p1=project(r*Math.cos(a),r*Math.sin(a),-th),p2=project(r*Math.cos(b),r*Math.sin(b),-th);
      const p3=project(r*Math.cos(b),r*Math.sin(b),th),p4=project(r*Math.cos(a),r*Math.sin(a),th);
      const mid=(a+b)/2, ridge=.5+.5*Math.cos(mid*38);
      const lit=Math.max(0,Math.sin(mid)*.35+Math.cos(mid)*.3+.35);
      const tone=faceSign>0 ? (.15+.45*ridge+.25*lit) : (.1+.25*ridge);
      poly([p1,p2,p3,p4],`rgba(${faceIsFront?166:85},${faceIsFront?128:75},${faceIsFront?55:38},${tone})`);
    }
    // face transform: local circular mint die projected into its live 3D ellipse
    const z=faceSign*th;
    const center=project(0,0,z), uu=project(1,0,z), vv=project(0,1,z);
    ctx.save();
    ctx.translate(center[0],center[1]);
    ctx.transform(uu[0]-center[0],uu[1]-center[1],vv[0]-center[0],vv[1]-center[1],0,0);
    ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.clip();

    let grad=ctx.createRadialGradient(-r*.34,-r*.42,r*.04,0,0,r*1.04);
    grad.addColorStop(0,pal[2]);grad.addColorStop(.15,pal[1]);grad.addColorStop(.54,pal[0]);grad.addColorStop(.82,pal[1]);grad.addColorStop(1,pal[3]);
    ctx.fillStyle=grad;ctx.fillRect(-r,-r,r*2,r*2);

    // circular machining rings
    for(let i=0;i<7;i++){ctx.beginPath();ctx.arc(0,0,r*(.2+i*.105),0,Math.PI*2);ctx.strokeStyle=`rgba(255,255,255,${.035+i*.009})`;ctx.lineWidth=1.1;ctx.stroke()}
    ctx.lineWidth=r*.036;ctx.strokeStyle=pal[2];ctx.globalAlpha=.62;ctx.beginPath();ctx.arc(0,0,r*.88,0,Math.PI*2);ctx.stroke();
    ctx.lineWidth=r*.014;ctx.strokeStyle=pal[3];ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(0,0,r*.78,0,Math.PI*2);ctx.stroke();
    // fixed environmental light appears to rake across the rotating metal
    const light=norm([-.55,-.62,.95]), lx=light[0]*u[0]+light[1]*u[1]+light[2]*u[2], ly=light[0]*v[0]+light[1]*v[1]+light[2]*v[2];
    const spec=ctx.createRadialGradient(lx*r*.73,ly*r*.73,0,lx*r*.73,ly*r*.73,r*.48);
    spec.addColorStop(0,'rgba(255,255,238,.96)');spec.addColorStop(.09,'rgba(255,255,255,.48)');spec.addColorStop(.43,'rgba(255,255,255,.10)');spec.addColorStop(1,'rgba(255,255,255,0)');
    ctx.globalCompositeOperation='screen';ctx.fillStyle=spec;ctx.fillRect(-r,-r,r*2,r*2);ctx.globalCompositeOperation='source-over';

    ctx.globalAlpha=1;
    if(faceIsFront){
      // raised mint emblem
      ctx.save();ctx.translate(0,5);
      ctx.shadowColor='rgba(0,0,0,.75)';ctx.shadowBlur=0;ctx.shadowOffsetX=5;ctx.shadowOffsetY=7;
      ctx.fillStyle=pal[3];ctx.beginPath();
      for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI*2/10, rr=i%2?67:112;let px=Math.cos(a)*rr,py=Math.sin(a)*rr;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath();ctx.fill();
      ctx.shadowOffsetX=-3;ctx.shadowOffsetY=-4;ctx.fillStyle=pal[2];ctx.beginPath();
      for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI*2/10,rr=i%2?60:103;let px=Math.cos(a)*rr,py=Math.sin(a)*rr;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath();ctx.fill();
      ctx.fillStyle=pal[0];ctx.beginPath();ctx.arc(0,0,43,0,Math.PI*2);ctx.fill();
      ctx.fillStyle=pal[2];ctx.font='900 45px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('W',0,4);
      ctx.restore();
      ctx.fillStyle=pal[2];ctx.font=`900 ${r*.09}px Arial`;ctx.textAlign='center';ctx.fillText('WASTEDTOKEN',0,-r*.58);ctx.font=`700 ${r*.055}px Arial`;ctx.fillText('MINT • EST. 2026 • MINT',0,r*.62);
    } else {
      ctx.fillStyle=pal[2];ctx.textAlign='center';ctx.font=`900 ${r*.23}px Arial`;ctx.fillText('10,000',0,-9);
      ctx.font=`900 ${r*.105}px Arial`;ctx.fillText('TOKENS',0,r*.16);
      ctx.font=`700 ${r*.045}px Arial`;ctx.fillText('SPEND WISELY. OR DON’T.',0,r*.55);
      ctx.beginPath();ctx.arc(0,0,r*.46,0,Math.PI*2);ctx.strokeStyle=pal[2];ctx.globalAlpha=.55;ctx.lineWidth=3;ctx.stroke();
      ctx.globalAlpha=1;ctx.font=`900 ${r*.09}px Arial`;ctx.fillText('₩',0,-r*.61);
    }
    ctx.restore();
  }
  function render(t){
    ctx.clearRect(0,0,W,H);
    drawCoin(ctx,{t});
  }
  function tick(now){if(!running)return;render(((now-start)%9000)/9000);raf=requestAnimationFrame(tick)}
  window.demo={canvas,setTime(t){running=false;cancelAnimationFrame(raf);render(Math.max(0,Math.min(1,t)))},pause(){running=false;cancelAnimationFrame(raf)}};
  raf=requestAnimationFrame(tick);

  document.querySelectorAll('.edition-canvas').forEach((el,index)=>{
    const dpr=Math.min(devicePixelRatio||1,2), size=360;
    el.width=size*dpr;el.height=size*dpr;
    const c=el.getContext('2d');c.scale(dpr,dpr);
    c.fillStyle='#0b1016';c.fillRect(0,0,size,size);
    const kind=['bronze','silver','gold','black'][index];
    drawCoin(c,{t:.11+index*.035,kind,mini:true,cx:180,cy:170,r:115,th:13});
  });
  document.querySelectorAll('.buy').forEach(b=>b.addEventListener('click',()=>{
    const toast=document.getElementById('toast');toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800);
  }));
})();
</script>
</body>
</html>
